//! Byte-for-byte parity of this port's verdicts against the JavaScript gate.
//!
//! The corpus is generated by `tools/gen-gate-verdicts.mjs`, which runs the
//! reference `gate.mjs` (and the frozen commit-807745d copy) over a corpus of
//! curves. The JSON is gitignored like every other oracle: it is an artifact of
//! the AGPL sibling repo, never vendored here.
//!
//! Set `AURI_GATE_VERDICTS` to point at a corpus from elsewhere. Without one the
//! suite reports a skip and passes, so CI stays green with no sibling checkout.

use std::collections::BTreeSet;
use std::path::PathBuf;

use auri_codec::Band;
use auri_gate::{GateMetrics, GateOptions, GateResult, Grid, Profile, Reason, ReasonValue, gate};

use serde::Deserialize;

/// Relative tolerance for an f64 both sides computed with the same operations:
/// far above the ~1e-16 the languages actually differ by, far below anything
/// that could hide a real disagreement.
const EPS: f64 = 1e-9;

/// Absolute tolerance for a *reported peak frequency* in Hz.
///
/// Golden-section refinement picks its branch from `fc > fd`, so a one-ulp
/// difference between V8's and Rust's `sin` can walk a perfectly flat peak to a
/// neighbouring point. The tolerance is still four orders of magnitude below
/// the densest grid interval (~9 Hz at 8 kHz), so it cannot hide a peak found
/// in the wrong place — only a plateau's dead centre.
const HZ_EPS: f64 = 1e-3;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Fixture {
    codes: Vec<String>,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    id: String,
    bands: serde_json::Value,
    preamp_db: f64,
    options: Options,
    expected: Verdict,
    metrics: Metrics,
    frozen: Option<Verdict>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Options {
    experimental: bool,
    grid: String,
    profile: String,
}

impl Options {
    fn to_options(&self) -> GateOptions {
        GateOptions {
            experimental: self.experimental,
            grid: if self.grid == "drag" {
                Grid::Drag
            } else {
                Grid::Full
            },
            profile: if self.profile == "yolo" {
                Profile::Yolo
            } else {
                Profile::Standard
            },
        }
    }
}

#[derive(Deserialize, Debug)]
#[serde(rename_all = "camelCase")]
struct Verdict {
    ok: bool,
    reasons: Vec<FixtureReason>,
    #[serde(default)]
    waived: Option<Vec<String>>,
    #[serde(default)]
    waived_reasons: Option<Vec<FixtureReason>>,
}

#[derive(Deserialize, Debug)]
#[serde(rename_all = "camelCase")]
struct FixtureReason {
    code: String,
    #[serde(default)]
    stage: Option<u32>,
    #[serde(default)]
    value: Option<serde_json::Value>,
    #[serde(default)]
    limit: Option<f64>,
}

#[derive(Deserialize, Default)]
#[serde(rename_all = "camelCase", default)]
struct Metrics {
    payload_crc: Option<String>,
    preamp_db: Option<f64>,
    quantized_preamp_db: Option<f64>,
    internal_audible: Option<FixturePeak>,
    output_audible: Option<FixturePeak>,
    output_full: Option<FixturePeak>,
    internal_full: Option<FixturePeak>,
    output_extended: Option<FixturePeak>,
    sections: Option<Vec<FixtureSection>>,
    prefix_audible: Option<Vec<FixturePrefix>>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct FixturePeak {
    db: f64,
    #[serde(default)]
    frequency_hz: Option<f64>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct FixtureSection {
    pole_radius: f64,
    full_peak_db: f64,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct FixturePrefix {
    stage: u32,
    db: f64,
}

fn corpus_path() -> PathBuf {
    if let Ok(path) = std::env::var("AURI_GATE_VERDICTS") {
        return PathBuf::from(path);
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/gate-verdicts.json")
}

/// Every comparison the test performs, so an empty corpus cannot pass silently.
#[derive(Default)]
struct Tally {
    numbers: usize,
    worst_db: f64,
    worst_hz: f64,
}

impl Tally {
    fn string(&mut self, where_: &str, want: &str, got: &str) {
        assert_eq!(
            got, want,
            "[{where_}] string mismatch: port {got:?}, oracle {want:?}"
        );
    }

    fn number(&mut self, where_: &str, want: f64, got: f64) {
        self.numbers += 1;
        let scale = 1.0 + want.abs().max(got.abs());
        let delta = (got - want).abs() / scale;
        self.worst_db = self.worst_db.max(delta);
        assert!(
            delta <= EPS,
            "[{where_}] {got} but the oracle says {want} (relative delta {delta:e})"
        );
    }

    /// A peak frequency, compared on the looser [`HZ_EPS`] scale.
    fn hz(&mut self, where_: &str, want: f64, got: f64) {
        self.numbers += 1;
        let delta = (got - want).abs();
        self.worst_hz = self.worst_hz.max(delta);
        assert!(
            delta <= HZ_EPS,
            "[{where_}] {got} Hz but the oracle says {want} Hz (delta {delta:e})"
        );
    }

    fn optional_number(&mut self, where_: &str, want: Option<f64>, got: Option<f64>) {
        match (want, got) {
            (Some(want), Some(got)) => self.number(where_, want, got),
            (None, None) => {}
            (want, got) => panic!("[{where_}] number mismatch: port {got:?}, oracle {want:?}"),
        }
    }
}

fn compare_reason(where_: &str, want: &FixtureReason, got: &Reason, tally: &mut Tally) {
    tally.string(where_, &want.code, got.code.as_str());
    assert_eq!(
        got.stage, want.stage,
        "[{where_}] stage mismatch: port {:?}, oracle {:?}",
        got.stage, want.stage
    );

    // `f:codec` carries the JavaScript message, which this port legitimately
    // words differently; only its presence is part of the contract.
    if want.code != "f:codec" {
        match &want.value {
            None | Some(serde_json::Value::Null) => {}
            Some(serde_json::Value::String(text)) => match &got.value {
                ReasonValue::Text(actual) => tally.string(where_, text, actual),
                other => panic!("[{where_}] value {other:?} but the oracle says {text:?}"),
            },
            Some(value @ serde_json::Value::Number(_)) => {
                let want = value.as_f64().expect("a JSON number");
                match got.value.as_number() {
                    Some(actual) => tally.number(where_, want, actual),
                    None => panic!(
                        "[{where_}] value {:?} but the oracle says {want}",
                        got.value
                    ),
                }
            }
            Some(other) => panic!("[{where_}] unexpected oracle value {other:?}"),
        }
    }

    match (want.limit, got.limit) {
        (Some(want), Some(got)) => tally.number(where_, want, got),
        (None, None) => {}
        (want, got) => panic!("[{where_}] limit mismatch: port {got:?}, oracle {want:?}"),
    }
}

fn compare_verdict(where_: &str, want: &Verdict, got: &GateResult, tally: &mut Tally) {
    assert_eq!(
        got.ok, want.ok,
        "[{where_}] ok mismatch\n  port:   {:?}\n  oracle: {:?}",
        got.reasons, want.reasons
    );
    assert_eq!(
        got.reasons.len(),
        want.reasons.len(),
        "[{where_}] reason count mismatch\n  port:   {:?}\n  oracle: {:?}",
        got.reasons,
        want.reasons
    );
    for (index, (want, got)) in want.reasons.iter().zip(got.reasons.iter()).enumerate() {
        compare_reason(&format!("{where_} reason #{index}"), want, got, tally);
    }

    match (&want.waived, &got.waived) {
        (None, None) => {}
        (Some(want), Some(got)) => {
            let want: Vec<&str> = want.iter().map(String::as_str).collect();
            let got: Vec<&str> = got.iter().map(|code| code.as_str()).collect();
            assert_eq!(got, want, "[{where_}] waived mismatch");
        }
        (want, got) => panic!("[{where_}] waived mismatch: port {got:?}, oracle {want:?}"),
    }

    match (&want.waived_reasons, &got.waived_reasons) {
        (None, None) => {}
        (Some(want), Some(got)) => {
            assert_eq!(
                got.len(),
                want.len(),
                "[{where_}] waivedReasons count mismatch"
            );
            for (index, (want, got)) in want.iter().zip(got.iter()).enumerate() {
                compare_reason(&format!("{where_} waived #{index}"), want, got, tally);
            }
        }
        (want, got) => panic!("[{where_}] waivedReasons mismatch: port {got:?}, oracle {want:?}"),
    }
}

fn compare_peak(
    where_: &str,
    want: &Option<FixturePeak>,
    db: Option<f64>,
    hz: Option<f64>,
    tally: &mut Tally,
) {
    let Some(want) = want else { return };
    tally.optional_number(&format!("{where_}.db"), Some(want.db), db);
    match (&want.frequency_hz, hz) {
        (Some(want), Some(got)) => tally.hz(&format!("{where_}.frequencyHz"), *want, got),
        (None, None) => {}
        (want, got) => panic!("[{where_}.frequencyHz] mismatch: port {got:?}, oracle {want:?}"),
    }
}

fn compare_metrics(where_: &str, want: &Metrics, got: &GateMetrics, tally: &mut Tally) {
    if let Some(want) = &want.payload_crc {
        let got = got
            .payload_crc
            .as_deref()
            .unwrap_or_else(|| panic!("[{where_}] no payloadCrc, the oracle says {want}"));
        tally.string(&format!("{where_}.payloadCrc"), want, got);
    }

    tally.optional_number(&format!("{where_}.preampDb"), want.preamp_db, got.preamp_db);
    tally.optional_number(
        &format!("{where_}.quantizedPreampDb"),
        want.quantized_preamp_db,
        got.quantized_preamp_db,
    );

    compare_peak(
        &format!("{where_}.internalAudible"),
        &want.internal_audible,
        got.internal_audible.map(|p| p.db),
        got.internal_audible.and_then(|p| p.frequency_hz),
        tally,
    );
    compare_peak(
        &format!("{where_}.outputAudible"),
        &want.output_audible,
        got.output_audible.map(|p| p.db),
        got.output_audible.and_then(|p| p.frequency_hz),
        tally,
    );
    compare_peak(
        &format!("{where_}.outputFull"),
        &want.output_full,
        got.output_full.map(|p| p.db),
        got.output_full.map(|p| p.frequency_hz),
        tally,
    );
    compare_peak(
        &format!("{where_}.internalFull"),
        &want.internal_full,
        got.internal_full.map(|p| p.db),
        got.internal_full.and_then(|p| p.frequency_hz),
        tally,
    );
    compare_peak(
        &format!("{where_}.outputExtended"),
        &want.output_extended,
        got.output_extended.map(|p| p.db),
        got.output_extended.and_then(|p| p.frequency_hz),
        tally,
    );

    if let Some(want) = &want.sections {
        let got = got
            .sections
            .as_ref()
            .unwrap_or_else(|| panic!("[{where_}] no sections, the oracle reports {}", want.len()));
        assert_eq!(got.len(), want.len(), "[{where_}] section count mismatch");
        for (index, (want, got)) in want.iter().zip(got.iter()).enumerate() {
            tally.number(
                &format!("{where_}.sections[{index}].poleRadius"),
                want.pole_radius,
                got.pole_radius,
            );
            tally.number(
                &format!("{where_}.sections[{index}].fullPeakDb"),
                want.full_peak_db,
                got.full_peak.db,
            );
        }
    }

    if let Some(want) = &want.prefix_audible {
        let got = got.prefix_audible.as_ref().unwrap_or_else(|| {
            panic!(
                "[{where_}] no prefixAudible, the oracle reports {}",
                want.len()
            )
        });
        assert_eq!(
            got.len(),
            want.len(),
            "[{where_}] prefixAudible count mismatch"
        );
        for (index, (want, got)) in want.iter().zip(got.iter()).enumerate() {
            assert_eq!(
                got.stage, want.stage,
                "[{where_}.prefixAudible[{index}].stage] mismatch"
            );
            tally.number(
                &format!("{where_}.prefixAudible[{index}].db"),
                want.db,
                got.db,
            );
        }
    }
}

#[test]
fn every_verdict_matches_the_javascript_gate() {
    let path = corpus_path();
    let Ok(text) = std::fs::read_to_string(&path) else {
        eprintln!(
            "SKIP parity: {} not found (run `node tools/gen-gate-verdicts.mjs`)",
            path.display()
        );
        return;
    };
    let fixture: Fixture = serde_json::from_str(&text).expect("the corpus parses");

    let mut tally = Tally::default();
    let mut covered = BTreeSet::new();

    for case in &fixture.cases {
        let bands: Vec<Band> = serde_json::from_value(case.bands.clone())
            .unwrap_or_else(|error| panic!("[{}] bands do not deserialise: {error}", case.id));
        let options = case.options.to_options();

        let actual = gate(&bands, case.preamp_db, options);
        compare_verdict(&case.id, &case.expected, &actual, &mut tally);
        compare_metrics(&case.id, &case.metrics, &actual.metrics, &mut tally);

        for reason in &actual.reasons {
            covered.insert(reason.code.as_str().to_owned());
        }
        for reason in actual.waived_reasons.iter().flatten() {
            covered.insert(reason.code.as_str().to_owned());
        }

        if let Some(frozen) = &case.frozen {
            let actual = gate(&bands, case.preamp_db, options);
            compare_verdict(
                &format!("{} (frozen)", case.id),
                frozen,
                &actual,
                &mut tally,
            );
        }
    }

    let missing: Vec<&str> = fixture
        .codes
        .iter()
        .filter(|code| !covered.contains(*code))
        .map(String::as_str)
        .collect();
    assert!(
        missing.is_empty(),
        "the corpus never exercised {} reason code(s): {}",
        missing.len(),
        missing.join(", ")
    );
    assert!(tally.numbers > 0, "the corpus contained nothing to compare");

    eprintln!(
        "parity: {} cases, {} reason codes, {} numeric comparisons \
         (worst relative delta {:e}, worst peak-frequency delta {:e} Hz)",
        fixture.cases.len(),
        covered.len(),
        tally.numbers,
        tally.worst_db,
        tally.worst_hz
    );
}
